param([string]$BaseUrl="http://localhost:3000");$ErrorActionPreference="Stop";function P($u,$b){Invoke-RestMethod -Method Post -Uri $u -ContentType application/json -Body($b|ConvertTo-Json -Depth 8)};$r="$BaseUrl/avos/planetary-production-intelligence";$s=Invoke-RestMethod "$r/status";$g=Invoke-RestMethod "$r/grids";$w=P "$r/workloads" @{objective="Planetary AVOS workload";requiredCapabilities=@("software-factory");origin="AE";preferredRegions=@("middle-east","europe");requiresHumanApproval=$true};$c=P "$r/workloads/$($w.id)/federate" @{};P "$r/workloads/$($w.id)/approve" @{approvedBy="human:khalifa"}|Out-Host;P "$r/knowledge/exchange" @{sourceGridId=$g[0].id;targetGridIds=@($g[1].id,$g[2].id);domain="production-optimization"}|Out-Host;P "$r/trust/establish" @{sourceGridId=$g[0].id;targetGridId=$g[1].id}|Out-Host;Invoke-RestMethod "$r/digital-twin"|Out-Host;P "$r/forecast" @{horizonHours=48}|Out-Host;$e=P "$r/evolution/propose" @{};P "$r/evolution/$($e.id)/approve" @{approvedBy="human:khalifa"}|Out-Host;P "$r/evolution/$($e.id)/deploy" @{}|Out-Host;$v=P "$r/final-review/run" @{};$z=P "$r/certification/certify" @{approvedBy="human:khalifa"};$s,$g,$w,$c,$v,$z|Format-List;if($v.score-ne100-or$z.status-ne"certified"){throw "PPI-SGF certification failed"};Write-Host "PPI-SGF MP1 passed all ten layers and certification." -ForegroundColor Green